import AppKit
import Foundation

func clickButton(bundleID: String, buttonTitle: String) {
    guard let app = NSRunningApplication.runningApplications(withBundleIdentifier: bundleID).first else {
        print("App not found")
        return
    }

    guard let appElement = AXUIElementCreateApplication(app.processIdentifier) as AXUIElement? else {
        print("Could not get app element")
        return
    }

    // Search for buttons in the app
    var windows: AnyObject?
    AXUIElementCopyAttributeValue(appElement, kAXWindowsAttribute as CFString, &windows)

    if let windowList = windows as? [AXUIElement] {
        for window in windowList {
            if let buttons = findAllButtons(in: window) {
                for button in buttons {
                    var title: AnyObject?
                    if AXUIElementCopyAttributeValue(button, kAXTitleAttribute as CFString, &title) == .success,
                       let buttonTitle = title as? String, buttonTitle == "Open" {
                        print("Found Open button, clicking it")
                        AXUIElementPerformAction(button, kAXPressAction as CFString)
                        return
                    }
                }
            }
        }
    }
}

func findAllButtons(in element: AXUIElement) -> [AXUIElement]? {
    var children: AnyObject?
    AXUIElementCopyAttributeValue(element, kAXChildrenAttribute as CFString, &children)

    var buttons: [AXUIElement] = []
    if let childList = children as? [AXUIElement] {
        for child in childList {
            var role: AnyObject?
            AXUIElementCopyAttributeValue(child, kAXRoleAttribute as CFString, &role)
            if let roleString = role as? String, roleString == kAXButtonRole {
                buttons.append(child)
            }
            if let subButtons = findAllButtons(in: child) {
                buttons.append(contentsOf: subButtons)
            }
        }
    }

    return buttons.isEmpty ? nil : buttons
}

// Try to click the Open button in the Simulator
clickButton(bundleID: "com.apple.CoreSimulator.CoreSimulatorService", buttonTitle: "Open")
