// Helper function to recursively print accessibility elements
func printElementTree(_ element: AXUIElement, indent: String = "") {
    var role: AnyObject?
    var title: AnyObject?
    var description: AnyObject?

    AXUIElementCopyAttributeValue(element, kAXRoleAttribute as CFString, &role)
    AXUIElementCopyAttributeValue(element, kAXTitleAttribute as CFString, &title)
    AXUIElementCopyAttributeValue(element, kAXDescriptionAttribute as CFString, &description)

    let roleStr = (role as? String) ?? "unknown"
    let titleStr = (title as? String) ?? ""
    let descStr = (description as? String) ?? ""

    print("\(indent)\(roleStr): \(titleStr) (\(descStr))")

    // Get children
    var children: AnyObject?
    AXUIElementCopyAttributeValue(element, kAXChildrenAttribute as CFString, &children)

    if let childList = children as? [AXUIElement] {
        for child in childList {
            printElementTree(child, indent: indent + "  ")
        }
    }
}

