        }

        // Look for Book Club room in the chat list
        let bookClubLabel = app.staticTexts.matching(NSPredicate(format: "label BEGINSWITH 'Book Club'")).element(boundBy: 0)

        if bookClubLabel.exists {
            print("✓ Found Book Club room")

            // Tap on the Book Club room
            if bookClubLabel.isHittable {
                bookClubLabel.tap()
                Thread.sleep(forTimeInterval: 2)
                print("✓ Opened Book Club room")

                // Find the message input field
                let messageField = app.textFields.firstMatch
                if messageField.exists && messageField.isHittable {
                    messageField.tap()
